import json

# Analyze B cell markers to classify cells
cell_ids = ['84275', '41908', '79793', '48424']

# Key B cell subtype markers
naive_markers = ['IGHD', 'IGHM', 'SELL']  # IgD+IgM+ for naive
memory_markers = ['CD27', 'IGHG', 'IGHA']  # CD27+ for memory, class-switched Igs
mz_markers = ['FCRL4', 'MZB1']  # Marginal zone

cell_info = {}
for cell_id in cell_ids:
    cell_idx = adata.obs_names.tolist().index(cell_id)

    naive_score = 0
    memory_score = 0
    mz_score = 0

    for gene in naive_markers:
        if gene in adata.var_names.tolist():
            val = adata[cell_idx, adata.var_names.tolist().index(gene)].X
            if hasattr(val, 'toarray'):
                val = val.toarray()[0, 0]
            naive_score += float(val)

    for gene in memory_markers:
        if gene in adata.var_names.tolist():
            val = adata[cell_idx, adata.var_names.tolist().index(gene)].X
            if hasattr(val, 'toarray'):
                val = val.toarray()[0, 0]
            memory_score += float(val)

    for gene in mz_markers:
        if gene in adata.var_names.tolist():
            val = adata[cell_idx, adata.var_names.tolist().index(gene)].X
            if hasattr(val, 'toarray'):
                val = val.toarray()[0, 0]
            mz_score += float(val)

    cell_info[cell_id] = {
        'naive_score': round(naive_score, 3),
        'memory_score': round(memory_score, 3),
        'mz_score': round(mz_score, 3)
    }

print("Classification scores:")
for cid, scores in cell_info.items():
    print(f"  {cid}: naive={scores['naive_score']}, memory={scores['memory_score']}, mz={scores['mz_score']}")

# Determine classification
results = {}
for cid, scores in cell_info.items():
    if scores['naive_score'] > scores['memory_score'] and scores['naive_score'] > scores['mz_score']:
        results[cid] = "naive"
    elif scores['memory_score'] > scores['naive_score'] and scores['memory_score'] > scores['mz_score']:
        results[cid] = "memory"
    else:
        results[cid] = "marginal_zone"

print("\nClassification:")
for cid, cls in results.items():
    print(f"  {cid}: {cls}")

print(json.dumps(results, indent=2))

